import{_ as e,H as s,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"29 | 最短路径：迪杰斯特拉（Dijkstra）算法与选择最节省时间的行走路线问题","description":"","frontmatter":{},"headers":[{"level":2,"title":"最短路径","slug":"最短路径","link":"#最短路径","children":[]},{"level":2,"title":"迪杰斯特拉（Dijkstra）算法详解","slug":"迪杰斯特拉-dijkstra-算法详解","link":"#迪杰斯特拉-dijkstra-算法详解","children":[]},{"level":2,"title":"∣V ∣2","slug":"∣v-∣2","link":"#∣v-∣2","children":[]},{"level":2,"title":"∣V ∣2","slug":"∣v-∣2-1","link":"#∣v-∣2-1","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后思考","slug":"课后思考","link":"#课后思考","children":[]}],"relativePath":"快速上手C++数据结构与算法/29｜最短路径：迪杰斯特拉（Dijkstra）算法与选择最节省时间的行走路线问题.md","filePath":"快速上手C++数据结构与算法/29｜最短路径：迪杰斯特拉（Dijkstra）算法与选择最节省时间的行走路线问题.md","lastUpdated":1795557152000}'),p={name:"快速上手C++数据结构与算法/29｜最短路径：迪杰斯特拉（Dijkstra）算法与选择最节省时间的行走路线问题.md"};function E(n,t,l,B,A,r){return s(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="_29-最短路径-迪杰斯特拉-dijkstra-算法与选择最节省时间的行走路线问题" tabindex="-1">29 | 最短路径：迪杰斯特拉（Dijkstra）算法与选择最节省时间的行走路线问题 <a class="header-anchor" href="#_29-最短路径-迪杰斯特拉-dijkstra-算法与选择最节省时间的行走路线问题" aria-label="Permalink to &quot;29 | 最短路径：迪杰斯特拉（Dijkstra）算法与选择最节省时间的行走路线问题&quot;">​</a></h1><p>你好，我是王健伟。</p><p>前面我们讲解了用普里姆（Prim）算法和克鲁斯卡尔（Kruskal）算法来寻找连通图的最小生成树，从而解决诸如如何修路费用最少这样的问题。这次我和你分享图的第二个实际用途——最短路径。那么，什么是最短路径呢？</p><h2 id="最短路径" tabindex="-1">最短路径 <a class="header-anchor" href="#最短路径" aria-label="Permalink to &quot;最短路径&quot;">​</a></h2><p>在带权图中，最短路径指的是图中两个顶点之间经过的边上权值之和最小的路径。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/1.png" alt=""></a></p><ul><li>图1 一个有向图（带权值）</li></ul><p>在图 1 中，顶点 A 到 E 之间的路径有多条，这里我举几个例子。</p><ul><li><p>A→B→E，顶点 A 到 E 的边上权值之和为 122。</p></li><li><p>A→D→C→E，顶点 A 到 E 的边上权值之和为 66。</p></li><li><p>A→D→B→E，顶点 A 到 E 的边上权值之和为 116。</p></li><li><p>A→D→C→B→E，顶点 A 到 E 的边上权值之和为 176。</p></li><li><p>A→D→C→F→E，顶点 A 到 E 的边上权值之和为 71。</p></li></ul><p>可以看到，A→D→C→E 所代表的的路径就是最短路径，权值之和为 66。那么对于一个带权有向图，给定一个顶点，如何求得该顶点到其余各个顶点的最短路径呢？其实这个问题也适用于带权无向图，因为带权无向图中的每条边就相当于带权有向图方向相反的两条边。</p><p>如果采用带权的邻接矩阵作为图 1 中有向图的存储结构，则结果如图 2 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/2.png" alt=""></a></p><ul><li>图2 图1所示有向图对应的带权邻接矩阵</li></ul><h2 id="迪杰斯特拉-dijkstra-算法详解" tabindex="-1">迪杰斯特拉（Dijkstra）算法详解 <a class="header-anchor" href="#迪杰斯特拉-dijkstra-算法详解" aria-label="Permalink to &quot;迪杰斯特拉（Dijkstra）算法详解&quot;">​</a></h2><p>荷兰籍的一位计算机科学家、计算机先驱之一迪杰斯特拉提出了一个按路径长度递增的次序产生最短路径的算法，称为迪杰斯特拉算法。以图 1 为例，我们看一看该算法的实现思路。</p><ol><li>设置一个集合 S 用于存放已经找到最短路径的顶点，该集合开始时只包含给定的第一个顶点。这个顶点也叫源顶点 / 起始顶点。我们就是要从该顶点找到其余各个顶点的最短路径。这里先把顶点 A 保存进去，这预示着从源顶点 A 开始已经找到了到目标顶点 A 的最短路径，毕竟本来这两个点就是同一个点。</li></ol><ul><li>S = {A}</li></ul><p>设置一个叫 dist 的数组，元素数量等同于图中顶点数量。该数组用于存放当前起始点到其他各个顶点的最短距离（权值最小），开始时该数组的内容就是图 2 中源顶点 A 所在行的值，即{0,22,∞,6,∞,∞}，因为这组数据正好代表源顶点 A 到其他各个顶点的距离。</p><p>设置一个叫 path 的数组，元素数量等同于图中的顶点数量。该数组用于记录每个顶点在最短路径上的前趋节点，里面的内容需要根据 dist 中的内容得出， dist 中对应下标位置是 0 或∞，则 path 对应位置是 -1。如果 dist 中对应下标位置有权值，那么 path 对应位置是源顶点的下标，所以开始时该数组内容为{-1,0,-1,0,-1,-1}。</p><ol start="2"><li>开始计算从源顶点 A 到不在集合 S 中的顶点的最短路径。</li></ol><p>A→B : 距离 =22</p><p>A→C : 距离 =∞ （∞表示 A 到 C 之间不直接相连）</p><p>A→D : 距离 =6</p><p>A→E : 距离 =∞</p><p>A→F : 距离 =∞</p><p>现在，得到了从顶点 A 到其他所有顶点的路径长度。我们从其中选出一条最短的路径，即：</p><p>A→D : 距离 =6</p><p>并把顶点 D 也放入到集合 S 中，表示源顶点 A 到顶点 D 的最短路径已找到，如图 3：</p><p>S = {A，D}</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/3.png" alt=""></a></p><ul><li>图3 选择与源顶点A最短的路径A→D</li></ul><ol start="3"><li>在增加了 D 顶点到集合后，顶点 A（经过顶点 D）到其他所有顶点是不是有更短的路径存在呢？</li></ol><p>这主要得看顶点 D 到达哪些顶点，根据图 2，顶点 D 对应的行数字是{∞,10,20,0,∞,∞}，这表示顶点 D 可以到达顶点 B、C。注意这里要求顶点 D 到达的目标顶点必须不能包含在集合 S中，所以看一下顶点 A 通过顶点 D 到达顶点 B 和到达顶点 C 的距离：</p><p>A→B : 距离 =(6+10)=16（通过 A→D→B 路径）</p><p>A→C : 距离 =(6+20)=26（通过 A→D→C 路径）</p><p>因为原来的顶点 A 到达顶点 B 和顶点 C 的距离是保存在 dist 数组的，dist 数组当前内容为{0,22,∞,6,∞,∞}。可以看到，原来 A→B 的距离是 22，A→C 的距离是∞，而现在 A→B 和A→C 的距离明显变得更小了，所以我们要更新 dist 数组中源顶点 A 到达顶点 B 和顶点 C 的距离，来保证 dist 数组中始终保存着源顶点 A 到其他各个顶点的最短距离。更新后 dist 数组的内容为{0,16,26,6,∞,∞}，这表示下面两个情况。</p><ul><li><p>源顶点 A 到达顶点 B 的最短距离为 16。</p></li><li><p>源顶点 A 到达顶点 C 的最短距离为 26。</p></li></ul><p>因为上述找最短路径找到了 D 顶点（下标 3），dist 数组中有两个位置做了修改，path 数组也要在相应位置做修改，即 path 数组中的内容也从原来的{-1,0,-1,0,-1,-1}更新为{-1,3,3,0,-1,-1}，这表示什么呢？</p><ul><li><p>源顶点 A 到达顶点 B 是通过顶点 D 到达的（B 的上一个顶点是 D）。</p></li><li><p>源顶点 A 到达顶点 C 也是通过顶点 D 到达的（C 的上一个顶点是 D）。</p></li></ul><ol start="4"><li>整理一下源顶点到其他顶点的距离信息：</li></ol><p>A→B : 距离 =16（通过 A→D→B 路径）</p><p>A→C : 距离 =26（通过 A→D→C 路径）</p><p>A→D : 距离 =6</p><p>A→E : 距离 =∞</p><p>A→F : 距离 =∞</p><p>因为顶点 D 已经在集合 S 中了，所以 A→D 这条路径就不考虑了，从其余的 4 条路径中选出一条最短的路径，注意，这 4 条路径的弧头顶点还没有找到从源顶点 A 到它们的最短路径。所以：</p><p>A→B : 距离 =16（通过 A→D→B 路径）</p><p>并把顶点 B 也放入到集合 S 中，表示源顶点 A 到顶点 B 的最短路径已找到，如图 4：</p><p>S = {A，D，B}</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/4.png" alt=""></a></p><ul><li>图4 选择与源顶点A最短的路径A→B（A→D→B）</li></ul><ol start="5"><li>在增加了 B 顶点到集合后，顶点 A（经过顶点 B）到其他所有顶点是不是有更短的路径存在呢？</li></ol><p>这主要得看顶点 B 到达哪些顶点。根据图 2，顶点 B 对应的行数字是{∞,0,∞,∞,100,∞}，这表示顶点 B 可以到达顶点 E。注意这里要求顶点 B 到达的目标顶点必须不能包含在集合 S 中。所以看一下顶点 A 通过顶点 B 到达顶点 E 的距离：</p><p>A→E : 距离 =(6+10+100)=116（通过 A→D→B→E 路径）</p><p>dist 数组当前内容为{0,16,26,6,∞,∞}，更新后 dist 数组的内容为{0,16,26,6,116,∞}，path 数组当前的内容为{-1,3,3,0,-1,-1}，更新后 path 数组的内容为{-1,3,3,0,1,-1}。</p><ol start="6"><li>整理一下源顶点到其他顶点的距离信息：</li></ol><p>A→B : 距离 =16（通过 A→D→B 路径）</p><p>A→C : 距离 =26（通过 A→D→C 路径）</p><p>A→D : 距离 =6</p><p>A→E : 距离 =116（通过 A→D→B→E 路径）</p><p>A→F : 距离 =∞</p><p>因为顶点 D、B 已经在集合 S 中了，所以 A→D、A→B 这两条路径就不考虑了，从其余的 3条路径中选出一条最短的路径，即：</p><p>A→C : 距离 =26（通过 A→D→C 路径）</p><p>并把顶点 C 也放入到集合 S 中，表示源顶点 A 到顶点 C 的最短路径已找到，如图 5：</p><p>S = {A，D，B，C}</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/5.png" alt=""></a></p><ul><li>图5 选择与源顶点A最短的路径A→C（A→D→C）</li></ul><ol start="7"><li>在增加了 C 顶点到集合后，顶点 A（经过顶点 C）到其他所有顶点是不是有更短的路径存在呢？</li></ol><p>这主要得看顶点 C 到达哪些顶点，根据图 2，顶点 C 对应的行数字是{∞,50,0,∞,40,10}，这表示顶点 C 可以到达顶点 B、E、F。注意这里要求顶点 C 到达的目标顶点必须不能包含在集合S 中，所以只需要看一下顶点 A 通过顶点 C 到达顶点 E、F 的距离：</p><p>A→E : 距离 =(6+20+40)=66（通过 A→D→C→E 路径）</p><p>A→F: 距离 =(6+20+10)=36（通过 A→D→C→F 路径）</p><p>dist 数组当前内容为{0,16,26,6,116,∞}，更新后 dist 数组的内容为{0,16,26,6,66,36}，path 数组当前的内容为{-1,3,3,0,-1,-1}，更新后 path 数组的内容为{-1,3,3,0,2,2}。</p><ol start="8"><li>整理一下源顶点到其他顶点的距离信息：</li></ol><p>A→B : 距离 =16（通过 A→D→B 路径）</p><p>A→C : 距离 =26（通过 A→D→C 路径）</p><p>A→D : 距离 =6</p><p>A→E : 距离 =66（通过 A→D→C→E 路径）</p><p>A→F : 距离 =36（通过 A→D→C→F 路径）</p><p>因为顶点 D、B、C 已经在集合 S 中了，所以 A→D、A→B、A→C 这 3 条路径就不考虑了，从其余的 2 条路径中选出一条最短的路径，即：</p><p>A→F : 距离 =36（通过 A→D→C→F 路径）</p><p>并把顶点 F 也放入到集合 S 中，表示源顶点 A 到顶点 F 的最短路径已找到，如图 6：</p><p>S = {A，D，B，C，F}</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/6.png" alt=""></a></p><ul><li>图6 选择与源顶点A最短的路径A→F（A→D→C→F）</li></ul><ol start="9"><li>在增加了 F 顶点到集合后，顶点 A（经过顶点 F）到其他所有顶点是不是有更短的路径存在呢？</li></ol><p>这主要得看顶点 F 到达哪些顶点，根据图 2，顶点 F 对应的行数字是{∞,∞,∞,65,35,∞}，这表示顶点 F 可以到达顶点 D、E。注意这里要求顶点 F 到达的目标顶点必须不能包含在集合 S中，所以只需要看一下顶点 A 通过顶点 F 到达顶点 E 的距离：</p><p>A→E : 距离 =(6+20+10+35)=71（通过 A→D→C→F→E 路径）</p><p>这个距离比原来 A→E 的距离更远，所以忽略。</p><p>dist 数组维持当前内容{0,16,26,6,66,36}，path 数组维持当前内容{-1,3,3,0,2,2}。</p><ol start="10"><li>整理一下源顶点到其他顶点的距离信息：</li></ol><p>A→B : 距离 =16（通过 A→D→B 路径）</p><p>A→C : 距离 =26（通过 A→D→C 路径）</p><p>A→D : 距离 =6</p><p>A→E : 距离 =66（通过 A→D→C→E 路径）</p><p>A→F : 距离 =36（通过 A→D→C→F 路径）</p><p>因为顶点 D、B、C、F 已经在集合 S 中了，所以 A→D、A→B、A→C、A→F 这 4 条路径就不考虑了，只剩下也只能选择如下路径，即：</p><p>A→E : 距离 =66（通过 A→D→C→E 路径）</p><p>并把顶点 E 也放入到集合 S 中，表示源顶点 A 到顶点 E 的最短路径已找到，如图 7：</p><p>S = {A，D，B，C，F，E}</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/7.png" alt=""></a></p><ul><li>图7 选择与源顶点A最短的路径A→E（A→D→C→E）</li></ul><ol start="11"><li>在增加了 E 顶点到集合后，顶点 A（经过顶点 E）到其他所有顶点是不是有更短的路径存在呢？ 没有。因为顶点 E 没有到达任何其他顶点。</li></ol><p>至此，集合 S 中已经包含了图中的所有顶点，迪杰斯特拉算法结束。此时：</p><p>dist 数组内容为：{0,16,26,6,66,36}</p><p>path 数组内容为：{-1,3,3,0,2,2}</p><p>通过上面两个数组的内容，就可以分析出从源顶点 A 到其他顶点的最短路径。那么我们来看两个更具体的问题。</p><ul><li>如何得到从源顶点 A 到顶点 B 的最短路径长度？</li></ul><p>第一就是查找 dist 数组，查找下标为 1（顶点 B）的元素值，发现是 16，这意味着从顶点 A到顶点 B 的最短路径长度是 16。第二就是看 path 数组以获得从顶点 A 到顶点 B 的最短路径“path[1] = 3；path[3]=0；”，因为 0 代表顶点 A 即源顶点，找到源顶点之后，就可以得到结果了，以反序将刚刚 path 数组的结果输出就是最短路径，即 0→3，这些数字代表顶点的下标，所以，顶点 A 到 B 的最短路径如图 8 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/8.png" alt=""></a></p><ul><li><p>图8 源顶点A顶点B的最短路径（A→D→B）</p></li><li><p>如何查找从源顶点 A 到顶点 E 的最短路径长度？</p></li></ul><p>第一就是查找 dist 数组，查找下标为 4（顶点 E）的元素值，发现是 66，这意味着从顶点 A到顶点 E 的最短路径长度是 66。第二就是看 path 数组以获得从顶点 A 到顶点 E 的最短路径“path[4] = 2；path[2] = 3；path[3] = 0”，因为 0 代表顶点 A 即源顶点，找到源顶点之后，就可以得到结果了，以反序将刚刚 path 数组的结果输出就是最短路径，即 0→3→2，这些数字代表顶点的下标，所以，顶点 A 到 E 的最短路径如图 9 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/9.png" alt=""></a></p><ul><li>图9 源顶点A顶点E的最短路径（A→D→C→E）</li></ul><p>想一想，为什么通过查找 path 数组就可以找到最短路径呢？这是因为在每次更改 dist 数组后都会在 path 数组中记录当前顶点的上一个顶点是谁。所以利用倒推的方式就可以把路径推导出来。</p><p>完整的实现迪杰斯特拉（Dijkstra）算法的类模板相关源码，参见课件中 GraphMatrix 类模板的定义与实现。这里我们重点看其中的 ShortestPath_Dijkstra() 成员函数的实现代码。</p><p>main 主函数中代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GraphMatrix&lt;​char&gt; gm;</span></span>
<span class="line"><span>gm.InsertVertex(&#39;A&#39;);</span></span>
<span class="line"><span>gm.InsertVertex(&#39;B&#39;);</span></span>
<span class="line"><span>gm.InsertVertex(&#39;C&#39;);</span></span>
<span class="line"><span>gm.InsertVertex(&#39;D&#39;);</span></span>
<span class="line"><span>gm.InsertVertex(&#39;E&#39;);</span></span>
<span class="line"><span>gm.InsertVertex(&#39;F&#39;);</span></span>
<span class="line"><span>//向图中插入边</span></span>
<span class="line"><span>gm.InsertEdge(&#39;A&#39;, &#39;B&#39;, 22); //22代表边的权值</span></span>
<span class="line"><span>gm.InsertEdge(&#39;A&#39;, &#39;D&#39;, 6);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;B&#39;, &#39;E&#39;, 100);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;C&#39;, &#39;B&#39;, 50);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;C&#39;, &#39;E&#39;, 40);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;C&#39;, &#39;F&#39;, 10);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;D&#39;, &#39;B&#39;, 10);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;D&#39;, &#39;C&#39;, 20);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;F&#39;, &#39;D&#39;, 65);</span></span>
<span class="line"><span>gm.InsertEdge(&#39;F&#39;, &#39;E&#39;, 35);</span></span>
<span class="line"><span>//显示图形</span></span>
<span class="line"><span>gm.DispGraph();</span></span>
<span class="line"><span>gm.ShortestPath_Dijkstra(&#39;A&#39;);</span></span></code></pre></div><p>执行结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/10.png" alt=""></a></p><p>从上述代码不难看到，迪杰斯特拉算法实现中使用的 dist 数组和前面讲过的普里姆算法中使用的 lowcost 数据非常类似。在实现代码中，采用了带权的邻接矩阵作为图的存储结构，算法中使用了双重循环，每重循环的循环次数都不会超过顶点数量，所以该算法的时间复杂度为 O(</p><h2 id="∣v-∣2" tabindex="-1">∣V ∣2 <a class="header-anchor" href="#∣v-∣2" aria-label="Permalink to &quot;∣V ∣2&quot;">​</a></h2><ul><li>)。</li></ul><p>迪杰斯特拉算法解决了从某个源顶点到图中其余各顶点的最短路径问题。可能你会问了，是否能够找到图中某个顶点开始到另一个特定顶点的最短路径？</p><p>其实这样做和求某个顶点开始到其他所有顶点最短路径并没有区别，依然要采用迪杰斯特拉算</p><h2 id="∣v-∣2-1" tabindex="-1">∣V ∣2 <a class="header-anchor" href="#∣v-∣2-1" aria-label="Permalink to &quot;∣V ∣2&quot;">​</a></h2><p>法不断计算从开始顶点到其他各个顶点的最短距离，所以时间复杂度仍旧是 O(</p><ul><li>)。所以，</li></ul><p>即便是寻找某两个点之间的最短路径，解决办法仍旧是选择其中一个作为源顶点，然后用迪杰斯特拉算法求出到其余顶点的最短路径，这些路径中肯定包含着到另外一个顶点的最短路径，除非这两个顶点之间不可达。</p><p>图的最短路径求解问题在实际生活中有非常实用的价值，应用广泛。比如城市公交或者城市地铁站都可以看作是一张图，其中的各个站点都可以看作是图中顶点。如果把全国交通图看成是一张图的话，那么各个城市就可以看作是图中的顶点。如图 10 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/11.png" alt=""></a></p><ul><li>图10 国内城市交通图</li></ul><p>在图 10 中，从一个城市到达另外一个城市有多种走法。</p><ul><li><p>如果把城市之间的距离作为权值，利用最短路径算法，可以找到从某个城市去到另外一个城市如何走距离最短。</p></li><li><p>如果把城市之间驱车所花费的时间作为权值，利用最短路径算法，可以找到从某个城市到另外一个城市如何走最节省时间。</p></li><li><p>如果把城市之间坐车所花费的金钱作为权值，利用最短路径算法，可以求解出如何乘车花费的金钱最少。</p></li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课我给出一个图来向你详细阐述最短路径的概念，然后提出了如何从某个顶点求得到其他各个顶点的最短路径的问题。从而引出了迪杰斯特拉（Dijkstra）算法——专门用来求从某个顶点到其他各个顶点最短路径的算法。</p><p>本节我用大量的篇幅阐述了迪杰斯特拉算法的详细实现过程，我们首先设置集合 S 来存放已经找到最短路径的顶点、设置 dist 数组存放当前起始点到其他各个顶点的最短距离、设置path 数组记录每个顶点在最短路径上的前趋节点。然后阐述详细的算法步骤。</p><p>充分理解这些算法的实现步骤是后序能够写出迪杰斯特拉算法代码的根本，否则即便是阅读别人实现的迪杰斯特拉算法，也会一头雾水。接着，我带你完成了整个迪杰斯特拉算法的实现代码。</p><p>迪杰斯特拉算法解决了从某个源顶点到其余各顶点的最短路径问题，在实际生活中有非常实用的价值，比如我为你举的几个例子，分别是从某个城市到另一个城市如何走距离最短、如何走最节省时间、如何乘车花费的金钱最少等。你可以举一反三，仔细想想还有哪些实际生活中的问题可以用迪杰斯特拉算法解决呢？</p><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">​</a></h2><p>许多城市的地铁线路非常繁杂，以深圳为例，如图 11 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/29/12.png" alt=""></a></p><ul><li>图11 深圳地铁线路图</li></ul><p>目前深圳地铁已经开通运营了 10 几条线路。对于一些行动不便的老人或者残障人士，乘坐地铁时，如果目的地特别远并且要换乘多次地铁才能达到，则经常希望换乘的次数尽可能少。怎样做到呢？</p>`,143)])])}const g=e(p,[["render",E]]);export{h as __pageData,g as default};
